<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$title,'subtitle'=>$this->role()==='borrower'?'Track the status of your barangay equipment requests.':'Review and process borrowing requests securely.']) ?><section class="panel"><div class="panel-head"><form class="toolbar" method="get"><input type="search" name="q" value="<?= esc((string)service('request')->getGet('q')) ?>" placeholder="Search request, borrower, or purpose"><select name="status"><option value="">All statuses</option><?php foreach(config('BantayGamit')->requestStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= service('request')->getGet('status')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><button class="btn" type="submit">Filter</button><?php if(service('request')->getGet('q')||service('request')->getGet('status')): ?><a class="btn ghost" href="<?= site_url('borrow-requests') ?>">Clear</a><?php endif; ?></form><?php if($this->role()==='borrower'): ?><a class="btn primary" href="<?= site_url('borrow-requests/new') ?>"><?= ui_icon('plus') ?> New Request</a><?php endif; ?></div><p class="result-count"><?= (int)$total ?> request(s)</p><?= view('borrow_requests/_table',['requests'=>$requests]) ?><?php if($pagerLinks): ?><div class="pager" aria-label="Borrow request pagination"><?= $pagerLinks ?></div><?php endif; ?></section><?= $this->endSection() ?>
